  ?p a ?cls .
  OPTIONAL { ?p brick:hasName ?name }
}

SELECT ?n ?type WHERE {
  ?e brick:hasName ?n .
  FILTER (?n LIKE "%CHW%" || ?n LIKE "%Chiller02%" || ?n LIKE "%SupplyFan%")
  ?e a ?type .
}

SELECT ?e ?lbl ?ifc ?type WHERE {
  ?e rdfs:label ?lbl .
  ?e a ?type .
  OPTIONAL { ?e ref;ifcName ?ifc }
}

