import csv
from collections import defaultdict

targets = {
    "CHWPump02": "a39e93e1-f68f-5e9e-b836-56293fd89fa7",
    "Chiller02": "6041ce4e-9251-5a23-9103-a13dcc247d28",
    "SupplyFan_AHU01": "4693f367-6f23-5b26-868f-f17e866f28b6",
}
date="2018-07-19"
sums=defaultdict(float); counts=defaultdict(int)
with open(VALUES_CSV) as f:
    r=csv.DictReader(f)
    for row in r:
        ts=row['timeseries_id']
        if ts in targets.values() and row['timestamp'].startswith(date):
            v=float(row['value'] or 0)
            for n,t in targets.items():
                if t==ts:
                    sums[n]+=v; counts[n]+=1

for n in targets:
    print(n, "sum(W)", sums[n], "-> kWh", sums[n]/1000, "n", counts[n])
